package gemspec_test

import (
	"strings"
	"testing"

	"mochi/package3/ruby/gemspec"
)

// goldenMinimal is the exact expected output for the minimal config test.
const goldenMinimal = `# frozen_string_literal: true
# Auto-generated by mochi pkg publish (MEP-76). Do not edit.

Gem::Specification.new do |spec|
  spec.name          = "my-gem"
  spec.version       = "0.1.0"
  spec.authors       = ["Alice"]
  spec.summary       = "A minimal gem."
  spec.license       = "MIT"

  spec.files         = Dir["lib/**/*.rb", "sig/**/*.rbs"]
  spec.require_paths = ["lib"]
end
`

// goldenFull is the exact expected output for the full config test.
const goldenFull = `# frozen_string_literal: true
# Auto-generated by mochi pkg publish (MEP-76). Do not edit.

Gem::Specification.new do |spec|
  spec.name          = "full-gem"
  spec.version       = "2.3.4"
  spec.authors       = ["Bob", "Carol"]
  spec.summary       = "Short summary."
  spec.description   = "A longer description of the gem."
  spec.homepage      = "https://example.com"
  spec.license       = "Apache-2.0"

  spec.files         = Dir["lib/**/*.rb", "sig/**/*.rbs"]
  spec.require_paths = ["lib"]

  spec.metadata = {
    "changelog_uri" => "https://example.com/CHANGELOG",
    "source_code_uri" => "https://example.com/src",
  }

  spec.add_runtime_dependency "nokogiri", "~> 1.16"
  spec.add_runtime_dependency "redis", ">= 5.0"
end
`

func minimalConfig() gemspec.PublishConfig {
	return gemspec.PublishConfig{
		Name:        "my-gem",
		Version:     "0.1.0",
		Summary:     "A minimal gem.",
		Authors:     []string{"Alice"},
		License:     "MIT",
	}
}

func fullConfig() gemspec.PublishConfig {
	return gemspec.PublishConfig{
		Name:        "full-gem",
		Version:     "2.3.4",
		Description: "A longer description of the gem.",
		Summary:     "Short summary.",
		Authors:     []string{"Bob", "Carol"},
		License:     "Apache-2.0",
		Homepage:    "https://example.com",
		Metadata: map[string]string{
			"source_code_uri": "https://example.com/src",
			"changelog_uri":   "https://example.com/CHANGELOG",
		},
		RuntimeDeps: []gemspec.GemDep{
			{Name: "redis", Constraint: ">= 5.0"},
			{Name: "nokogiri", Constraint: "~> 1.16"},
		},
	}
}

func TestEmit_MinimalConfig(t *testing.T) {
	t.Run("exact golden output", func(t *testing.T) {
		got := gemspec.Emit(minimalConfig())
		if got != goldenMinimal {
			t.Errorf("minimal gemspec mismatch.\nwant:\n%s\ngot:\n%s", goldenMinimal, got)
		}
	})
}

func TestEmit_FullConfig(t *testing.T) {
	t.Run("exact golden output", func(t *testing.T) {
		got := gemspec.Emit(fullConfig())
		if got != goldenFull {
			t.Errorf("full gemspec mismatch.\nwant:\n%s\ngot:\n%s", goldenFull, got)
		}
	})
}

func TestEmit_GemNameOverride(t *testing.T) {
	t.Run("GemName overrides Name", func(t *testing.T) {
		cfg := minimalConfig()
		cfg.GemName = "overridden-gem"
		got := gemspec.Emit(cfg)
		if !strings.Contains(got, `spec.name          = "overridden-gem"`) {
			t.Errorf("GemName override not reflected; got:\n%s", got)
		}
	})

	t.Run("Name used when GemName empty", func(t *testing.T) {
		cfg := minimalConfig()
		cfg.GemName = ""
		got := gemspec.Emit(cfg)
		if !strings.Contains(got, `spec.name          = "my-gem"`) {
			t.Errorf("Name not used when GemName empty; got:\n%s", got)
		}
	})
}

func TestEmit_SummaryFallback(t *testing.T) {
	t.Run("summary from description first sentence", func(t *testing.T) {
		cfg := minimalConfig()
		cfg.Summary = ""
		cfg.Description = "This is the summary. And more text."
		got := gemspec.Emit(cfg)
		if !strings.Contains(got, `spec.summary       = "This is the summary."`) {
			t.Errorf("summary fallback not working; got:\n%s", got)
		}
	})

	t.Run("description omitted when same as summary", func(t *testing.T) {
		cfg := minimalConfig()
		cfg.Summary = "A minimal gem."
		cfg.Description = "A minimal gem."
		got := gemspec.Emit(cfg)
		if strings.Contains(got, "spec.description") {
			t.Errorf("description should not appear when equal to summary; got:\n%s", got)
		}
	})
}

func TestEmit_RuntimeDepsSorted(t *testing.T) {
	t.Run("deps sorted alphabetically", func(t *testing.T) {
		cfg := minimalConfig()
		cfg.RuntimeDeps = []gemspec.GemDep{
			{Name: "zlib", Constraint: "~> 1.0"},
			{Name: "addressable", Constraint: ">= 2.8"},
			{Name: "nokogiri", Constraint: "~> 1.16"},
		}
		got := gemspec.Emit(cfg)
		addrIdx := strings.Index(got, "addressable")
		nokIdx := strings.Index(got, "nokogiri")
		zlibIdx := strings.Index(got, "zlib")
		if !(addrIdx < nokIdx && nokIdx < zlibIdx) {
			t.Errorf("deps not sorted alphabetically; got:\n%s", got)
		}
	})

	t.Run("deterministic on repeated calls", func(t *testing.T) {
		cfg := fullConfig()
		first := gemspec.Emit(cfg)
		second := gemspec.Emit(cfg)
		if first != second {
			t.Errorf("Emit is not deterministic")
		}
	})
}

func TestEmit_MetadataSorted(t *testing.T) {
	t.Run("metadata keys sorted alphabetically", func(t *testing.T) {
		cfg := minimalConfig()
		cfg.Metadata = map[string]string{
			"z_key": "z_val",
			"a_key": "a_val",
			"m_key": "m_val",
		}
		got := gemspec.Emit(cfg)
		aIdx := strings.Index(got, "a_key")
		mIdx := strings.Index(got, "m_key")
		zIdx := strings.Index(got, "z_key")
		if !(aIdx < mIdx && mIdx < zIdx) {
			t.Errorf("metadata keys not sorted; got:\n%s", got)
		}
	})
}

func TestEmit_FrozenStringLiteral(t *testing.T) {
	t.Run("output starts with frozen_string_literal", func(t *testing.T) {
		got := gemspec.Emit(minimalConfig())
		if !strings.HasPrefix(got, "# frozen_string_literal: true\n") {
			t.Errorf("gemspec missing frozen_string_literal pragma; got prefix: %q", got[:50])
		}
	})
}

func TestEmit_NoHomepage(t *testing.T) {
	t.Run("homepage omitted when empty", func(t *testing.T) {
		cfg := minimalConfig()
		cfg.Homepage = ""
		got := gemspec.Emit(cfg)
		if strings.Contains(got, "spec.homepage") {
			t.Errorf("homepage should not appear when empty; got:\n%s", got)
		}
	})
}

func TestValidate_MissingFields(t *testing.T) {
	tests := []struct {
		name    string
		cfg     gemspec.PublishConfig
		wantErr string
	}{
		{
			name:    "empty name",
			cfg:     gemspec.PublishConfig{Version: "1.0.0", Authors: []string{"A"}, Summary: "s"},
			wantErr: "name is required",
		},
		{
			name:    "empty version",
			cfg:     gemspec.PublishConfig{Name: "gem", Authors: []string{"A"}, Summary: "s"},
			wantErr: "version is required",
		},
		{
			name:    "empty authors",
			cfg:     gemspec.PublishConfig{Name: "gem", Version: "1.0.0", Summary: "s"},
			wantErr: "authors is required",
		},
		{
			name:    "empty summary and description",
			cfg:     gemspec.PublishConfig{Name: "gem", Version: "1.0.0", Authors: []string{"A"}},
			wantErr: "summary is required",
		},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			errs := gemspec.Validate(tc.cfg)
			if len(errs) == 0 {
				t.Fatalf("expected validation error containing %q, got none", tc.wantErr)
			}
			found := false
			for _, e := range errs {
				if strings.Contains(e, tc.wantErr) {
					found = true
					break
				}
			}
			if !found {
				t.Errorf("expected error containing %q; got %v", tc.wantErr, errs)
			}
		})
	}
}

func TestValidate_ValidConfig(t *testing.T) {
	t.Run("valid minimal config has no errors", func(t *testing.T) {
		errs := gemspec.Validate(minimalConfig())
		if len(errs) != 0 {
			t.Errorf("expected no errors for valid config; got %v", errs)
		}
	})

	t.Run("valid full config has no errors", func(t *testing.T) {
		errs := gemspec.Validate(fullConfig())
		if len(errs) != 0 {
			t.Errorf("expected no errors for full config; got %v", errs)
		}
	})

	t.Run("gem_name override satisfies name requirement", func(t *testing.T) {
		cfg := gemspec.PublishConfig{
			GemName: "override-name",
			Version: "1.0.0",
			Authors: []string{"Author"},
			Summary: "A summary.",
		}
		errs := gemspec.Validate(cfg)
		if len(errs) != 0 {
			t.Errorf("GemName should satisfy name requirement; got %v", errs)
		}
	})
}
